import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> fruits = new ArrayList<>();
        fruits.add("apple");
        fruits.add("banana");
        fruits.add(1, "cherry");
        System.out.println(fruits);
        fruits.remove("apple");
        System.out.println(fruits.get(0) + " " + fruits.size());
        System.out.println(fruits.contains("banana"));
    }
}
